import math

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

N = 78
total_paths = 0

# We calculate S = sum_{r=0}^{N-1} sum_{c=0}^{N-1} C(r+c, r)
for r in range(N):
    for c in range(N):
        # C(r+c, r) is the number of paths from (0, 0) to (r, c)
        paths_to_rc = combinations(r + c, r)
        total_paths += paths_to_rc

print(f"N={N}")
print(f"Total number of good paths: {total_paths}")

